// Call from a useEffect in VesselArchiveSite; returns a cleanup function.
// No global listeners, tracking, bookings or personal-data collection.
function mountGroomsmenPage(root) {
  if (!root) return () => {};
  let disposed = false;
  const previousMode = document.body.getAttribute("data-va-groomsmen");
  document.body.setAttribute("data-va-groomsmen", "true");
  const robots = ["robots", "googlebot"].map(name => {
    const existing = document.head.querySelector(`meta[name="${name}"]`);
    const previous = existing ? existing.getAttribute("content") : null;
    const node = existing || document.createElement("meta");
    node.setAttribute("name", name);
    node.setAttribute("content", GROOMSMEN_META.robots);
    if (!existing) document.head.appendChild(node);
    return {node, existing, previous};
  });
  const onClick = async event => {
    const button = event.target.closest && event.target.closest("[data-gm-copy]");
    if (!button || !root.contains(button)) return;
    const text = button.getAttribute("data-gm-copy");
    const status = root.querySelector(".gm-copy-status");
    try {
      if (!navigator.clipboard || !window.isSecureContext) throw new Error("Manual copy required");
      await navigator.clipboard.writeText(text);
      if (disposed) return;
      button.textContent = "Copied";
      if (status) status.textContent = "Room-block code copied.";
    } catch (_) {
      if (disposed) return;
      // Works on file:// previews and browsers where clipboard permission is denied.
      const code = root.querySelector(".gm-copy-row code");
      if (code) { const range = document.createRange(); range.selectNodeContents(code); const selection = window.getSelection(); if (selection) {selection.removeAllRanges(); selection.addRange(range);} }
      if (status) status.textContent = "Code selected. Press and hold, or copy with your keyboard.";
    }
  };
  root.addEventListener("click", onClick);
  return () => {
    disposed = true;
    root.removeEventListener("click", onClick);
    if (previousMode === null) document.body.removeAttribute("data-va-groomsmen");
    else document.body.setAttribute("data-va-groomsmen", previousMode);
    robots.forEach(({node,existing,previous}) => {
      if (!existing) node.remove();
      else if (previous === null) node.removeAttribute("content");
      else node.setAttribute("content", previous);
    });
  };
}


